export type StringKey = keyof typeof DICT;

const STORAGE_KEY = 'chokepoint.lang';
const listeners = new Set<() => void>();
let lang: Lang = 'en';
let revision = 0;

function detect(): Lang {
  try {
    if (typeof localStorage !== 'undefined') {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored === 'fa' || stored === 'en') return stored;
    }
    if (typeof navigator !== 'undefined' && navigator.language?.toLowerCase().startsWith('fa')) return 'fa';
  } catch {
    /* storage may be unavailable (private mode, tests) */
  }
  return 'en';
}

function applyDocument(): void {
  if (typeof document === 'undefined') return;
  const root = document.documentElement;
  root.lang = lang;
  root.dir = lang === 'fa' ? 'rtl' : 'ltr';
  document.body?.classList.toggle('lang-fa', lang === 'fa');
}

export function initLang(): void {
  lang = detect();
  applyDocument();
}

export function getLang(): Lang {
  return lang;
}

export function isRTL(): boolean {
  return lang === 'fa';
}

export function langRevision(): number {
  return revision;
}

export function setLang(next: Lang): void {
  if (next === lang) return;
  lang = next;
  revision += 1;
  try {
    localStorage.setItem(STORAGE_KEY, next);
  } catch {
    /* persistence is best-effort */
  }
  applyDocument();
  for (const listener of listeners) listener();
}

export function toggleLang(): Lang {
  setLang(lang === 'fa' ? 'en' : 'fa');
  return lang;
}

export function onLangChange(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export function t(key: StringKey, vars?: Record<string, string | number>): string {
  const entry = DICT[key] as Entry;
  let text: string = lang === 'fa' ? entry[1] : entry[0];
  if (vars) {
    for (const [name, value] of Object.entries(vars)) {
      text = text.split(`{${name}}`).join(String(value));
    }
  }
  return text;
}

/** Localised display name for any data record carrying a `name_fa` field. */
export function localName(record: { name: string; name_fa?: string }): string {
  return lang === 'fa' && record.name_fa ? record.name_fa : record.name;
}

/** Localised one-line mechanical effect for map nodes. */
export function localEffect(record: { effect: string; effect_fa?: string }): string {
  return lang === 'fa' && record.effect_fa ? record.effect_fa : record.effect;
}

initLang();
